import { ChangeDetectionStrategy, Component, ElementRef, computed, input, model, output, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzCheckboxModule } from 'ng-zorro-antd/checkbox';
import { NzInputModule } from 'ng-zorro-antd/input';
import { TablerIconComponent, IconFilter, IconRestore, IconSearch, IconPlus } from '@tabler/icons-angular';
import { HrmOption, HrmOptionGroup } from '../shared/hrm-option';
import { HrmInput } from './hrm-input';
import { HrmInputNumber } from './hrm-input-number';
import { HrmSelect } from './hrm-select';
import { HrmSegmented } from './hrm-segmented';
import { HrmDatePicker } from './hrm-date-picker';
import { HrmRangePicker } from './hrm-range-picker';

/** Kiểu control của 1 điều kiện lọc. */
export type HrmFilterType = 'text' | 'select' | 'multi' | 'number' | 'date-range' | 'segmented';

/** Toán tử lọc: `id` là MÃ ỔN ĐỊNH (đi vào [(conditions)] + backend map query, không đổi theo
 *  ngôn ngữ); `label` là nhãn hiển thị (i18n bên gọi cấp khi override). */
export interface HrmFilterOperator {
  id: string;
  label: string;
  /** Ô giá trị đi kèm: 'default' theo type · 'range' 2 ô số · 'date' 1 ô ngày · 'none' không cần
   *  (preset "Hôm nay", "Để trống"… — vẫn tính là 1 điều kiện). Bỏ trống = 'default'. */
  input?: 'default' | 'range' | 'date' | 'none';
}

/** Định nghĩa 1 TRƯỜNG lọc (config-driven). */
export interface HrmFilterFieldDef {
  key: string;
  label: string;
  /** Tabler icon trước nhãn. */
  icon?: unknown;
  type: HrmFilterType;
  /** Override bộ toán tử (bỏ trống dùng mặc định theo type; segmented không có toán tử). */
  operators?: HrmFilterOperator[];
  /** id toán tử mặc định khi thêm hàng — bỏ trống lấy toán tử ĐẦU TIÊN có ô giá trị
   *  (không bao giờ mặc định toán tử valueless — tránh tự thành điều kiện khi user chưa nhập gì). */
  defaultOperator?: string;
  /** Danh mục cho select/multi/segmented. Segmented: option ĐẦU TIÊN = "tất cả" (không tính là lọc). */
  options?: HrmOption[];
  placeholder?: string;
  /** Nhóm trong picker "Thêm điều kiện" (VD "Thường dùng"). */
  group?: string;
  /** Luôn hiện, không gỡ được, không xuất hiện trong picker (VD Từ khóa). */
  fixed?: boolean;
  /** Hiện sẵn khi mở lần đầu (gỡ được qua picker). */
  visible?: boolean;
}

/** 1 điều kiện ĐÃ áp: trường + MÃ toán tử + giá trị (string | string[] | number |
 *  [number|null, number|null] | Date | Date[] | null tuỳ type/toán tử). */
export interface HrmFilterCondition {
  key: string;
  operator: string;
  value: unknown;
}

interface DraftRow { operator: string; value: unknown; }

const EMPTY_OPS: HrmFilterOperator[] = [
  { id: 'empty', label: 'Để trống', input: 'none' },
  { id: 'notEmpty', label: 'Không trống', input: 'none' },
];

/** Toán tử mặc định theo type — theo thẩm định nghiệp vụ HRM + UX:
 *  - text/select/multi kèm "Để trống/Không trống" (audit thiếu dữ liệu: chưa gán quản lý, chưa có email…)
 *  - number dùng nhãn chữ, không ký hiệu trần
 *  - date: preset theo LỊCH VN (tuần/tháng/kỳ, không rolling) + hướng tương lai (HĐ sắp hết hạn)
 *    + "Từ ngày/Trước ngày" 1 ô (xét thâm niên, chốt danh sách trước mốc). */
const DEFAULT_OPS: Record<HrmFilterType, HrmFilterOperator[]> = {
  text: [
    { id: 'contains', label: 'Chứa' },
    { id: 'notContains', label: 'Không chứa' },
    { id: 'startsWith', label: 'Bắt đầu bằng' },
    ...EMPTY_OPS,
  ],
  select: [
    { id: 'is', label: 'Là' },
    { id: 'isNot', label: 'Khác' },
    ...EMPTY_OPS,
  ],
  multi: [
    { id: 'in', label: 'Là một trong' },
    { id: 'notIn', label: 'Không thuộc' },
    ...EMPTY_OPS,
  ],
  number: [
    { id: 'eq', label: 'Bằng' },
    { id: 'gte', label: 'Từ (≥)' },
    { id: 'lte', label: 'Đến (≤)' },
    { id: 'between', label: 'Trong khoảng', input: 'range' },
  ],
  'date-range': [
    { id: 'between', label: 'Trong khoảng' },
    { id: 'onOrAfter', label: 'Từ ngày', input: 'date' },
    { id: 'before', label: 'Trước ngày', input: 'date' },
    { id: 'today', label: 'Hôm nay', input: 'none' },
    { id: 'thisWeek', label: 'Tuần này', input: 'none' },
    { id: 'thisMonth', label: 'Tháng này', input: 'none' },
    { id: 'lastMonth', label: 'Tháng trước', input: 'none' },
    { id: 'next30d', label: '30 ngày tới', input: 'none' },
  ],
  segmented: [],
};

/** hrm-filter-panel — BỘ LỌC NÂNG CAO dạng builder (mỗi hàng = trường · toán tử · giá trị).
 *  Nút trigger (badge đếm, viền brand khi có lọc) mở panel: header (tiêu đề + phụ đề + ↺ Đặt lại) ·
 *  các hàng điều kiện theo `fields` config · "+ Thêm điều kiện" (picker: tìm + tick trường theo nhóm) ·
 *  footer Hủy / Đặt lại / Áp dụng. DRAFT: chỉnh trong panel chưa ăn — Áp dụng mới commit vào
 *  [(conditions)] + emit (apply); Hủy đóng bỏ draft; Đặt lại xoá draft (giữ mở).
 *  Toán tử lưu MÃ ổn định (contains/in/between/today…), nhãn hiển thị tách riêng → i18n/backend an toàn.
 *  Control giá trị theo type + op.input: text→hrm-input · select/multi→hrm-select (multi = tags ×) ·
 *  number→hrm-input-number (between = 2 ô) · date-range→hrm-range-picker (Từ ngày/Trước ngày = 1 ô
 *  hrm-date-picker; preset Hôm nay/Tháng này… không cần ô) · segmented→hrm-segmented (option đầu =
 *  "tất cả", không tính lọc).
 *  <hrm-filter-panel [fields]="defs" [(conditions)]="conds" (apply)="load()" /> */
@Component({
  selector: 'hrm-filter-panel',
  imports: [FormsModule, NzDropDownModule, NzCheckboxModule, NzInputModule, TablerIconComponent,
    HrmInput, HrmInputNumber, HrmSelect, HrmSegmented, HrmDatePicker, HrmRangePicker],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <button type="button" class="fp" [class.fp--active]="activeCount() > 0"
      nz-dropdown [nzDropdownMenu]="panel" nzTrigger="click" [nzVisible]="open()" (nzVisibleChange)="onVisible($event)">
      <tabler-icon class="fp-ic" [icon]="$any(icon())" [size]="15" />
      <span class="fp-label">{{ label() }}</span>
      @if (activeCount() > 0) {
        <span class="fp-sep"></span>
        <span class="fp-count">{{ activeCount() }}</span>
      }
    </button>

    <nz-dropdown-menu #panel>
      <div class="fp-panel" #panelEl>
        <div class="fp-head">
          <div class="fp-head-l">
            <div class="fp-head-t">{{ panelTitle() || label() }}</div>
            @if (panelSubtitle()) { <div class="fp-head-s">{{ panelSubtitle() }}</div> }
          </div>
          <button type="button" class="fp-reset-link" (click)="resetDraft()">
            <tabler-icon [icon]="restoreIcon" [size]="14" /> {{ resetLabel() }}
          </button>
        </div>

        <div class="fp-body">
          @for (f of shownFields(); track f.key) {
            <div class="fp-row">
              <div class="fp-row-label">
                @if (f.icon) { <tabler-icon class="fp-row-ic" [icon]="$any(f.icon)" [size]="16" /> }
                <span>{{ f.label }}</span>
              </div>
              @if (opsOf(f).length) {
                <hrm-select class="fp-row-op" [options]="opFlatOptions(f)" [groups]="opGroupOptions(f)"
                  [allowClear]="false" [showSearch]="false"
                  [ngModel]="rowOf(f.key).operator" (ngModelChange)="setOp(f.key, $event)" />
              }
              <div class="fp-row-value" [class.fp-row-value--full]="!opsOf(f).length">
                @switch (inputKind(f, rowOf(f.key).operator)) {
                  @case ('none') {
                    <!-- Toán tử tự đủ nghĩa (Hôm nay, Để trống…) — giữ slot để layout không nhảy. -->
                    <span class="fp-row-novalue">{{ noValueText() }}</span>
                  }
                  @case ('range') {
                    <div class="fp-num-range">
                      <hrm-input-number [ngModel]="$any(numRange(f.key)[0])" (ngModelChange)="setNumRange(f.key, 0, $event)" />
                      <span class="fp-num-sep">–</span>
                      <hrm-input-number [ngModel]="$any(numRange(f.key)[1])" (ngModelChange)="setNumRange(f.key, 1, $event)" />
                    </div>
                  }
                  @case ('date') {
                    <hrm-date-picker [ngModel]="$any(rowOf(f.key).value)" (ngModelChange)="setVal(f.key, $event)" />
                  }
                  @default {
                    @switch (f.type) {
                      @case ('text') {
                        <hrm-input [placeholder]="f.placeholder ?? ''"
                          [ngModel]="$any(rowOf(f.key).value)" (ngModelChange)="setVal(f.key, $event)" />
                      }
                      @case ('select') {
                        <hrm-select [options]="f.options ?? []" [placeholder]="f.placeholder ?? ''"
                          [ngModel]="rowOf(f.key).value" (ngModelChange)="setVal(f.key, $event)" />
                      }
                      @case ('multi') {
                        <hrm-select [multiple]="true" [options]="f.options ?? []" [placeholder]="f.placeholder ?? ''"
                          [ngModel]="rowOf(f.key).value" (ngModelChange)="setVal(f.key, $event)" />
                      }
                      @case ('number') {
                        <hrm-input-number [placeholder]="f.placeholder ?? ''"
                          [ngModel]="$any(rowOf(f.key).value)" (ngModelChange)="setVal(f.key, $event)" />
                      }
                      @case ('date-range') {
                        <hrm-range-picker
                          [ngModel]="$any(rowOf(f.key).value)" (ngModelChange)="setVal(f.key, $event)" />
                      }
                      @case ('segmented') {
                        <hrm-segmented [options]="$any(f.options ?? [])"
                          [ngModel]="$any(rowOf(f.key).value)" (ngModelChange)="setVal(f.key, $event)" />
                      }
                    }
                  }
                }
              </div>
            </div>
          }

          <!-- Thêm/gỡ trường — picker nested dropdown: tìm + tick theo nhóm. -->
          <button type="button" class="fp-add" nz-dropdown [nzDropdownMenu]="picker" nzTrigger="click"
            [nzVisible]="pickerOpen()" (nzVisibleChange)="pickerOpen.set($event)">
            <tabler-icon [icon]="plusIcon" [size]="15" /> {{ addLabel() }}
          </button>
        </div>

        <div class="fp-foot">
          <button type="button" class="fp-btn" (click)="cancel()">{{ cancelLabel() }}</button>
          <button type="button" class="fp-btn" (click)="resetDraft()">{{ resetLabel() }}</button>
          <button type="button" class="fp-btn fp-btn--primary" (click)="commit()">{{ applyLabel() }}</button>
        </div>
      </div>
    </nz-dropdown-menu>

    <nz-dropdown-menu #picker>
      <div class="fp-picker">
        <div class="fp-picker-search">
          <tabler-icon [icon]="searchIcon" [size]="15" />
          <input nz-input type="text" [value]="pickerQuery()" (input)="onPickerSearch($event)"
            [attr.placeholder]="searchPlaceholder() || null" />
        </div>
        @for (g of pickerGroups(); track g.label) {
          <div class="fp-picker-group">{{ g.label }}</div>
          @for (f of g.fields; track f.key) {
            <button type="button" class="fp-picker-row" (click)="toggleField(f.key)">
              <label nz-checkbox class="fp-picker-cb" [nzChecked]="shownKeys().has(f.key)"></label>
              <span class="fp-picker-label">{{ f.label }}</span>
            </button>
          }
        }
      </div>
    </nz-dropdown-menu>
  `,
  host: { class: 'hrm-filter-panel' },
  styles: [`
:host { display: inline-block; }

/* Trigger — cùng ngôn ngữ quick-filter: bo góc theo config theme, viền brand khi có lọc. */
.fp {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 12px; border-radius: var(--radius-lg); cursor: pointer;
  background: var(--bg-surface); border: 1px solid var(--border-sub);
  font-family: var(--font-sans); font-size: var(--fs-13); color: var(--text-body);
  transition: border-color var(--duration-fast, .15s) var(--ease-out, ease),
              background var(--duration-fast, .15s) var(--ease-out, ease);
}
.fp:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
.fp--active { border-color: var(--primary-base); }
.fp-ic { flex: none; color: var(--text-sub); }
.fp-label { white-space: nowrap; }
.fp-sep { width: 1px; align-self: stretch; margin: 1px 2px; background: var(--border-sub); }
.fp-count { white-space: nowrap; font-weight: 600; color: var(--text-strong); }
.fp:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; }

/* Panel builder — flex cột + max-height: header/footer GHIM, body cuộn → thêm bao nhiêu điều kiện
   nút Áp dụng vẫn luôn bấm được (fix bug panel nở vượt màn). */
.fp-panel {
  width: min(640px, 94vw); max-height: min(72vh, 620px);
  display: flex; flex-direction: column;
  padding: 14px 16px 12px;
  background: var(--bg-surface); border: 1px solid var(--border-sub);
  border-radius: var(--radius-xl); box-shadow: var(--shadow-regular-md);
  font-family: var(--font-sans);
}
.fp-head { flex: none; display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; margin-bottom: 4px; }
.fp-head-t { font-size: var(--fs-16); font-weight: 700; color: var(--text-strong); }
.fp-head-s { margin-top: 2px; font-size: var(--fs-12); color: var(--text-sub); }
.fp-reset-link {
  flex: none; display: inline-flex; align-items: center; gap: 4px;
  border: 0; background: transparent; padding: 2px 0; cursor: pointer;
  font-family: inherit; font-size: var(--fs-13); color: var(--primary-base); font-weight: 500;
}
.fp-reset-link:hover { text-decoration: underline; }

.fp-body { flex: 1 1 auto; min-height: 0; overflow-y: auto; }
.fp-row {
  display: grid; grid-template-columns: 185px 148px 1fr; gap: 10px; align-items: center;
  padding: 12px 0; border-bottom: 1px solid var(--border-soft);
}
.fp-row:first-child { border-top: 1px solid var(--border-soft); margin-top: 8px; }
.fp-row-label {
  display: flex; align-items: center; gap: 8px; min-width: 0;
  font-size: var(--fs-13); font-weight: 500; color: var(--text-strong);
}
.fp-row-ic { flex: none; color: var(--text-sub); }
/* Nhãn dài (VD "Có hợp đồng chính thức") — cho xuống dòng, KHÔNG cắt cụt để user luôn đọc đủ. */
.fp-row-label span { white-space: normal; line-height: 1.35; }
.fp-row-op { min-width: 0; }
.fp-row-value { min-width: 0; }
.fp-row-value--full { grid-column: 2 / -1; }
.fp-row-novalue { display: block; padding: 4px 2px; font-size: var(--fs-13); color: var(--text-disabled); font-style: italic; }
.fp-num-range { display: flex; align-items: center; gap: 6px; min-width: 0; }
.fp-num-range hrm-input-number { flex: 1; min-width: 0; }
.fp-num-sep { flex: none; color: var(--text-soft); }

/* "+ Thêm điều kiện" — dashed, full-width. */
.fp-add {
  display: flex; align-items: center; justify-content: center; gap: 6px; width: 100%;
  margin-top: 12px; padding: 9px 12px; cursor: pointer;
  border: 1px dashed var(--border-sub); border-radius: var(--radius-md);
  background: transparent; font-family: inherit; font-size: var(--fs-13); color: var(--primary-base); font-weight: 500;
}
.fp-add:hover { border-color: var(--primary-base); background: var(--primary-bg-subtle); }

.fp-foot { flex: none; display: flex; justify-content: flex-end; gap: 8px; padding-top: 12px; }
.fp-btn {
  padding: 6px 16px; cursor: pointer; text-align: center;
  border: 1px solid var(--border-sub); border-radius: var(--radius-md);
  background: var(--bg-surface); font-family: inherit; font-size: var(--fs-13); color: var(--text-body);
}
.fp-btn:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
.fp-btn--primary {
  background: var(--primary-base); border-color: var(--primary-base); color: var(--primary-foreground);
  font-weight: 500;
}
.fp-btn--primary:hover { background: var(--primary-hover); border-color: var(--primary-hover); color: var(--primary-foreground); }

/* Picker "Thêm điều kiện" */
.fp-picker {
  min-width: 240px; max-width: 300px; max-height: 380px; overflow-y: auto; padding: 6px;
  background: var(--bg-surface); border: 1px solid var(--border-sub);
  border-radius: var(--radius-xl); box-shadow: var(--shadow-regular-md);
  font-family: var(--font-sans);
}
.fp-picker-search { display: flex; align-items: center; gap: 8px; padding: 4px 10px 8px; border-bottom: 1px solid var(--border-soft); color: var(--text-soft); }
.fp-picker-search input.ant-input.ant-input {
  flex: 1; min-width: 0; padding: 4px 0; border: 0; background: transparent; box-shadow: none;
  font-size: var(--fs-13); color: var(--text-body);
}
.fp-picker-group {
  font-size: var(--fs-11); font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em;
  color: var(--text-soft); padding: 10px 10px 4px;
}
.fp-picker-row {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 7px 10px; border: 0; background: transparent; cursor: pointer;
  border-radius: var(--radius-md); text-align: left;
  font-family: inherit; font-size: var(--fs-13); color: var(--text-body);
}
.fp-picker-row:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
.fp-picker-cb { flex: none; pointer-events: none; }
.fp-picker-label { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  `],
})
export class HrmFilterPanel {
  /** Nhãn nút trigger. */
  readonly label = input('Bộ lọc');
  /** Tiêu đề panel — bỏ trống dùng label. */
  readonly panelTitle = input('');
  /** Phụ đề dưới tiêu đề (VD "Lọc nhân viên theo các tiêu chí bạn chọn"). */
  readonly panelSubtitle = input('');
  /** Tabler icon nút trigger. */
  readonly icon = input<unknown>(IconFilter);
  /** Config các trường lọc. */
  readonly fields = input<HrmFilterFieldDef[]>([]);
  /** Điều kiện ĐÃ áp (two-way) — operator là MÃ; chỉ chứa hàng có nghĩa; badge đếm từ đây. */
  readonly conditions = model<HrmFilterCondition[]>([]);
  /** Nhãn i18n — bên gọi cấp. */
  readonly resetLabel = input('Đặt lại');
  readonly applyLabel = input('Áp dụng');
  readonly cancelLabel = input('Hủy');
  readonly addLabel = input('Thêm điều kiện');
  readonly searchPlaceholder = input('Tìm điều kiện');
  /** Text chỗ ô giá trị khi toán tử không cần nhập (giữ slot chống nhảy layout). */
  readonly noValueText = input('Không cần nhập giá trị');
  /** Nhãn 2 nhóm trong dropdown toán tử khi có preset/valueless (i18n bên gọi cấp). */
  readonly opGroupCompare = input('So sánh');
  readonly opGroupQuick = input('Chọn nhanh');
  /** Trạng thái mở (two-way). */
  readonly open = model(false);
  /** Bấm Áp dụng — payload = điều kiện có nghĩa; panel tự đóng. */
  readonly apply = output<HrmFilterCondition[]>();
  /** Bấm Đặt lại (header/footer) — draft về rỗng, panel giữ mở. */
  readonly clear = output<void>();

  protected readonly restoreIcon = IconRestore;
  protected readonly searchIcon = IconSearch;
  protected readonly plusIcon = IconPlus;

  protected readonly pickerOpen = signal(false);
  protected readonly pickerQuery = signal('');
  /** Trường đang hiện trong panel. */
  protected readonly shownKeys = signal<Set<string>>(new Set());
  /** Draft: key → {operator(id), value} — chỉ commit khi Áp dụng. */
  private readonly draft = signal<Map<string, DraftRow>>(new Map());

  protected readonly activeCount = computed(() => this.conditions().length);

  protected readonly shownFields = computed<HrmFilterFieldDef[]>(() =>
    this.fields().filter((f) => this.shownKeys().has(f.key)));

  protected opsOf(f: HrmFilterFieldDef): HrmFilterOperator[] {
    return f.operators ?? DEFAULT_OPS[f.type];
  }
  private opDef(f: HrmFilterFieldDef, id: string): HrmFilterOperator | undefined {
    return this.opsOf(f).find((o) => o.id === id);
  }
  /** Loại ô giá trị cho toán tử hiện tại. */
  protected inputKind(f: HrmFilterFieldDef, opId: string): 'default' | 'range' | 'date' | 'none' {
    return this.opDef(f, opId)?.input ?? 'default';
  }
  /** Dropdown toán tử: có preset/valueless → chia 2 nhóm (So sánh / Chọn nhanh) cho rõ mô hình. */
  protected opGroupOptions(f: HrmFilterFieldDef): HrmOptionGroup[] {
    const ops = this.opsOf(f);
    const quick = ops.filter((o) => o.input === 'none');
    if (!quick.length) return [];
    const compare = ops.filter((o) => o.input !== 'none');
    return [
      { label: this.opGroupCompare(), options: compare.map((o) => ({ value: o.id, label: o.label })) },
      { label: this.opGroupQuick(), options: quick.map((o) => ({ value: o.id, label: o.label })) },
    ];
  }
  protected opFlatOptions(f: HrmFilterFieldDef): HrmOption[] {
    if (this.opGroupOptions(f).length) return [];
    return this.opsOf(f).map((o) => ({ value: o.id, label: o.label }));
  }

  protected rowOf(key: string): DraftRow {
    return this.draft().get(key) ?? this.emptyRow(this.fields().find((f) => f.key === key));
  }

  /** Toán tử mặc định của field: defaultOperator → toán tử ĐẦU TIÊN có ô giá trị (không lấy valueless). */
  private defaultOp(f: HrmFilterFieldDef): string {
    const ops = this.opsOf(f);
    if (f.defaultOperator && ops.some((o) => o.id === f.defaultOperator)) return f.defaultOperator;
    return (ops.find((o) => (o.input ?? 'default') !== 'none') ?? ops[0])?.id ?? '';
  }
  private emptyRow(f: HrmFilterFieldDef | undefined): DraftRow {
    if (!f) return { operator: '', value: null };
    const op = this.defaultOp(f);
    switch (f.type) {
      case 'text': return { operator: op, value: '' };
      case 'multi': return { operator: op, value: [] };
      case 'segmented': return { operator: op, value: f.options?.[0]?.value ?? '' };
      default: return { operator: op, value: null };
    }
  }
  /** Hàng coi là "chưa lọc" (không commit, không đếm). Toán tử valueless → LUÔN là điều kiện.
   *  Segmented: option đầu = tất cả. Number khoảng: cần ít nhất 1 đầu. */
  private isEmpty(f: HrmFilterFieldDef, r: DraftRow): boolean {
    const kind = this.inputKind(f, r.operator);
    if (kind === 'none') return false;
    const v = r.value;
    if (v == null) return true;
    if (kind === 'range') return !Array.isArray(v) || (v[0] == null && v[1] == null);
    if (kind === 'date') return false; // đã non-null ở trên
    if (f.type === 'text') return String(v).trim() === '';
    if (f.type === 'multi') return !Array.isArray(v) || v.length === 0;
    if (f.type === 'segmented') return v === (f.options?.[0]?.value ?? '');
    if (f.type === 'date-range') return !Array.isArray(v) || v.length !== 2;
    return v === '';
  }

  protected onVisible(v: boolean): void {
    this.open.set(v);
    if (v) {
      this.seedDraft();
      this.nudgeOverlay();
    } else {
      this.pickerOpen.set(false);
    }
  }
  /** Mở panel: dựng draft từ điều kiện ĐÃ áp + trường mặc định. */
  private seedDraft(): void {
    const applied = new Map(this.conditions().map((c) => [c.key, c]));
    const shown = new Set<string>();
    const draft = new Map<string, DraftRow>();
    for (const f of this.fields()) {
      const isShown = f.fixed || f.visible || applied.has(f.key);
      if (!isShown) continue;
      shown.add(f.key);
      const a = applied.get(f.key);
      draft.set(f.key, a ? { operator: a.operator, value: a.value } : this.emptyRow(f));
    }
    this.shownKeys.set(shown);
    this.draft.set(draft);
  }

  protected setOp(key: string, op: string): void {
    const f = this.fields().find((x) => x.key === key);
    const cur = this.rowOf(key);
    const m = new Map(this.draft());
    /* Đổi toán tử làm đổi HÌNH DẠNG giá trị (khoảng ↔ đơn ↔ 1 ngày ↔ không cần ô) → reset giá trị
       để không commit shape sai; cùng shape thì giữ giá trị đã nhập. */
    const shapeChanged = !!f && this.inputKind(f, op) !== this.inputKind(f, cur.operator);
    m.set(key, { operator: op, value: shapeChanged ? this.emptyRow(f).value : cur.value });
    this.draft.set(m);
  }
  protected setVal(key: string, val: unknown): void {
    const m = new Map(this.draft());
    m.set(key, { ...this.rowOf(key), value: val });
    this.draft.set(m);
  }
  protected numRange(key: string): [number | null, number | null] {
    const v = this.rowOf(key).value;
    return Array.isArray(v) ? [v[0] ?? null, v[1] ?? null] : [null, null];
  }
  protected setNumRange(key: string, idx: 0 | 1, val: number | null): void {
    const cur = this.numRange(key);
    const next: [number | null, number | null] = idx === 0 ? [val, cur[1]] : [cur[0], val];
    this.setVal(key, next);
  }

  protected commit(): void {
    const out: HrmFilterCondition[] = [];
    for (const f of this.shownFields()) {
      const r = this.rowOf(f.key);
      if (!this.isEmpty(f, r)) out.push({ key: f.key, operator: r.operator, value: r.value });
    }
    this.conditions.set(out);
    this.apply.emit(out);
    this.open.set(false);
  }
  protected cancel(): void { this.open.set(false); }
  protected resetDraft(): void {
    const draft = new Map<string, DraftRow>();
    for (const f of this.shownFields()) draft.set(f.key, this.emptyRow(f));
    this.draft.set(draft);
    this.clear.emit();
  }

  /* ---- Picker ---- */
  protected onPickerSearch(e: Event): void { this.pickerQuery.set((e.target as HTMLInputElement).value); }
  private norm(s: string): string {
    return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[\u0111]/g, 'd');
  }
  /** Trường gỡ/thêm được (không fixed), lọc theo tìm kiếm, gom theo group giữ thứ tự xuất hiện. */
  protected readonly pickerGroups = computed<{ label: string; fields: HrmFilterFieldDef[] }[]>(() => {
    const q = this.norm(this.pickerQuery().trim());
    const groups: { label: string; fields: HrmFilterFieldDef[] }[] = [];
    for (const f of this.fields()) {
      if (f.fixed) continue;
      if (q && !this.norm(f.label).includes(q)) continue;
      const label = f.group ?? '';
      let g = groups.find((x) => x.label === label);
      if (!g) { g = { label, fields: [] }; groups.push(g); }
      g.fields.push(f);
    }
    return groups;
  });
  protected toggleField(key: string): void {
    const shown = new Set(this.shownKeys());
    const m = new Map(this.draft());
    if (shown.has(key)) {
      shown.delete(key);
      m.delete(key);
    } else {
      shown.add(key);
      if (!m.has(key)) m.set(key, this.emptyRow(this.fields().find((f) => f.key === key)));
    }
    this.shownKeys.set(shown);
    this.draft.set(m);
    this.nudgeOverlay();
  }

  private readonly panelEl = viewChild<ElementRef<HTMLDivElement>>('panelEl');

  /** Panel đổi chiều cao SAU khi overlay đã mở (thêm/gỡ hàng) — CDK không tự reposition nên
   *  footer có thể trôi khỏi viewport (bug: không bấm được Áp dụng). Tự đo khoảng trống còn lại
   *  dưới mép trên panel và GHIM max-height theo đó: body cuộn, footer luôn trong màn.
   *  Overlay attach bất đồng bộ → đo trễ 2 nhịp; viewChild có thể chưa thấy template trong
   *  overlay → fallback query DOM (chỉ 1 dropdown mở tại 1 thời điểm). */
  private nudgeOverlay(): void {
    if (typeof window === 'undefined') return;
    /* setTimeout thay vì rAF — rAF bị treo vô hạn ở tab/pane ẩn, đo hụt. */
    setTimeout(() => {
      const el = this.panelEl()?.nativeElement
        ?? (document.querySelector('.fp-panel') as HTMLDivElement | null);
      if (!el) return;
      const top = el.getBoundingClientRect().top;
      const room = Math.max(260, window.innerHeight - top - 16);
      el.style.maxHeight = `${room}px`;
    }, 80);
  }
}
